import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MapComponent from "../MapComponent";
import "./HousePredictionForm.css";

export default function HousePredictionForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    location: "",
    area: "",
    propertyType: "",
    bedrooms: "",
    bathrooms: "",
    year: "",
    condition: "",
    latitude: "",
    longitude: "",
    nearHospital: false, hospitalDistance: "", hospitalNA: false,
    nearSchool: false, schoolDistance: "", schoolNA: false,
    nearRailway: false, railwayDistance: "", railwayNA: false,
    nearBus: false, busDistance: "", busNA: false
  });

  const [coordinates, setCoordinates] = useState({ lat: null, lng: null });
  const [result, setResult] = useState();
  const [loading, setLoading] = useState(false);

  const handleChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const getCurrentLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          const { latitude, longitude } = position.coords;
          setCoordinates({ lat: latitude, lng: longitude });
          setForm((prev) => ({
            ...prev,
            latitude,
            longitude
          }));
          const geoApiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY;
          try {
            const resp = await fetch(
              `https://maps.googleapis.com/maps/api/geocode/json?latlng=${latitude},${longitude}&key=${geoApiKey}`
            );
            const data = await resp.json();
            if (data.status === "OK") {
              const rooftopResult = data.results.find(
                (r) => r.geometry.location_type === "ROOFTOP"
              );
              setForm((prev) => ({
                ...prev,
                location: (rooftopResult || data.results[0]).formatted_address,
              }));
            } else {
              alert(`Failed to get address: ${data.status} - ${data.error_message || ""}`);
            }
          } catch (error) {
            alert("Error fetching location address.");
          }
        },
        () => alert("Permission denied or unable to get location."),
        { enableHighAccuracy: true }
      );
    } else {
      alert("Geolocation is not supported by this browser.");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setResult(undefined);
    setLoading(true);
    try {
      const response = await fetch(`${process.env.REACT_APP_BACKEND_URL}/predict/house`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await response.json();
      setResult(data.price);
    } catch {
      setResult("Prediction failed.");
    }
    setLoading(false);
  };

  return (
    <div className="house-predict-root">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Home
      </button>
      <div className="house-predict-panels">
        <div className="property-details-card">
          <div className="property-header">
            <span className="icon">
              <img src="/icons/house.png" alt="" />
            </span>
            <span className="property-title">Property Details</span>
          </div>
          <div className="property-desc">
            Enter the details of the house to get an accurate price prediction
          </div>

          <form onSubmit={handleSubmit} className="property-form">
            <div className="form-group">
              <label className="form-label">Location</label>
              <div className="input-with-icon">
                <span className="input-icon">📍</span>
                <input
                  name="location"
                  type="text"
                  placeholder="e.g., Downtown, Suburb Name"
                  value={form.location}
                  onChange={handleChange}
                  required
                />
                <button
                  type="button"
                  className="location-btn"
                  onClick={getCurrentLocation}
                >
                  Use My Location
                </button>
              </div>
            </div>

            {/* Map Picker */}
            <div className="form-group">
              <label className="form-label">Choose Location on Map:</label>
              <MapComponent
                lat={coordinates.lat}
                lng={coordinates.lng}
                onLocationSelect={(lat, lng) => {
                  setCoordinates({ lat, lng });
                  setForm(f => ({ ...f, latitude: lat, longitude: lng }));
                }}
              />
              {coordinates.lat && coordinates.lng && (
                <div style={{ fontSize: "0.9em", marginTop: 4 }}>
                  Selected: {coordinates.lat}, {coordinates.lng}
                </div>
              )}
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Area (sq ft)</label>
                <input
                  name="area"
                  type="number"
                  min="0"
                  placeholder="1500"
                  value={form.area}
                  onChange={handleChange}
                  required
                />
              </div>
              <div className="form-group">
                <label className="form-label">Property Type</label>
                <select
                  name="propertyType"
                  value={form.propertyType}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select type</option>
                  <option>Apartment</option>
                  <option>Villa</option>
                  <option>Independent House</option>
                  <option>Duplex</option>
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Bedrooms</label>
                <select
                  name="bedrooms"
                  value={form.bedrooms}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select</option>
                  {[1,2,3,4,5].map(b => (
                    <option key={b}>{b}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Bathrooms</label>
                <select
                  name="bathrooms"
                  value={form.bathrooms}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select</option>
                  {[1,2,3,4,5].map(b => (
                    <option key={b}>{b}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Year Built</label>
                <input
                  name="year"
                  type="number"
                  min="1900"
                  max={new Date().getFullYear()}
                  placeholder="2015"
                  value={form.year}
                  onChange={handleChange}
                />
              </div>
              <div className="form-group">
                <label className="form-label">Condition</label>
                <select
                  name="condition"
                  value={form.condition}
                  onChange={handleChange}
                >
                  <option value="">Select condition</option>
                  <option>Excellent</option>
                  <option>Good</option>
                  <option>Needs Renovation</option>
                </select>
              </div>
            </div>

            {/* --- Facilities --- */}
            {/* Hospital */}
            <div className="form-group">
              <label>
                <input
                  type="checkbox"
                  checked={form.nearHospital}
                  onChange={e =>
                    setForm(f => ({
                      ...f,
                      nearHospital: e.target.checked,
                      hospitalNA: false
                    }))
                  }
                />{" "}
                Near Hospital
              </label>
              {form.nearHospital && !form.hospitalNA && (
                <input
                  type="number"
                  min="0"
                  step="0.1"
                  placeholder="Distance from hospital (km)"
                  value={form.hospitalDistance}
                  onChange={e =>
                    setForm(f => ({ ...f, hospitalDistance: e.target.value }))
                  }
                  required
                />
              )}
              {form.nearHospital && (
                <label style={{ marginLeft: 8 }}>
                  <input
                    type="checkbox"
                    checked={form.hospitalNA}
                    onChange={e =>
                      setForm(f => ({
                        ...f,
                        hospitalNA: e.target.checked,
                        hospitalDistance: "",
                        nearHospital: !e.target.checked
                      }))
                    }
                  />
                  Not Applicable
                </label>
              )}
            </div>

            {/* School */}
            <div className="form-group">
              <label>
                <input
                  type="checkbox"
                  checked={form.nearSchool}
                  onChange={e =>
                    setForm(f => ({
                      ...f,
                      nearSchool: e.target.checked,
                      schoolNA: false
                    }))
                  }
                />{" "}
                Near School
              </label>
              {form.nearSchool && !form.schoolNA && (
                <input
                  type="number"
                  min="0"
                  step="0.1"
                  placeholder="Distance from school (km)"
                  value={form.schoolDistance}
                  onChange={e =>
                    setForm(f => ({ ...f, schoolDistance: e.target.value }))
                  }
                  required
                />
              )}
              {form.nearSchool && (
                <label style={{ marginLeft: 8 }}>
                  <input
                    type="checkbox"
                    checked={form.schoolNA}
                    onChange={e =>
                      setForm(f => ({
                        ...f,
                        schoolNA: e.target.checked,
                        schoolDistance: "",
                        nearSchool: !e.target.checked
                      }))
                    }
                  />
                  Not Applicable
                </label>
              )}
            </div>

            {/* Railway */}
            <div className="form-group">
              <label>
                <input
                  type="checkbox"
                  checked={form.nearRailway}
                  onChange={e =>
                    setForm(f => ({
                      ...f,
                      nearRailway: e.target.checked,
                      railwayNA: false
                    }))
                  }
                />{" "}
                Near Railway Station
              </label>
              {form.nearRailway && !form.railwayNA && (
                <input
                  type="number"
                  min="0"
                  step="0.1"
                  placeholder="Distance from railway station (km)"
                  value={form.railwayDistance}
                  onChange={e =>
                    setForm(f => ({
                      ...f,
                      railwayDistance: e.target.value
                    }))
                  }
                  required
                />
              )}
              {form.nearRailway && (
                <label style={{ marginLeft: 8 }}>
                  <input
                    type="checkbox"
                    checked={form.railwayNA}
                    onChange={e =>
                      setForm(f => ({
                        ...f,
                        railwayNA: e.target.checked,
                        railwayDistance: "",
                        nearRailway: !e.target.checked
                      }))
                    }
                  />
                  Not Applicable
                </label>
              )}
            </div>

            {/* Bus Stand */}
            <div className="form-group">
              <label>
                <input
                  type="checkbox"
                  checked={form.nearBus}
                  onChange={e =>
                    setForm(f => ({
                      ...f,
                      nearBus: e.target.checked,
                      busNA: false
                    }))
                  }
                />{" "}
                Near Bus Stand
              </label>
              {form.nearBus && !form.busNA && (
                <input
                  type="number"
                  min="0"
                  step="0.1"
                  placeholder="Distance from bus stand (km)"
                  value={form.busDistance}
                  onChange={e =>
                    setForm(f => ({ ...f, busDistance: e.target.value }))
                  }
                  required
                />
              )}
              {form.nearBus && (
                <label style={{ marginLeft: 8 }}>
                  <input
                    type="checkbox"
                    checked={form.busNA}
                    onChange={e =>
                      setForm(f => ({
                        ...f,
                        busNA: e.target.checked,
                        busDistance: "",
                        nearBus: !e.target.checked
                      }))
                    }
                  />
                  Not Applicable
                </label>
              )}
            </div>

            <button className="predict-btn" type="submit" disabled={loading}>
              {loading ? "Predicting..." : "Predict House Price"}
            </button>
          </form>
        </div>

        {/* Price output */}
        <div className="price-prediction-card">
          <div className="price-header">
            <span className="price-icon">₹</span>
            <span className="price-title">Price Prediction</span>
          </div>
          <div className="price-desc">
            Your estimated house price will appear here
          </div>
          <div className="price-output">
            {!!result ? (
              <div className="price-result">
                <span className="result-value">₹ {result}</span>
              </div>
            ) : (
              <div className="result-placeholder">
                <span className="result-calc-icon">🧮</span>
                <span>
                  Fill out the form to see your price prediction
                </span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
